1	import { checkResult } from "./result-checker.mjs";
2	import { overlapsProtectedSpan } from "./protected-spans.mjs";
3	import { createSourceUnitManifest } from "./source-units.mjs";
4	import { ContractError, SCHEMA_VERSION, requireObject, sha256, stableJson } from "./lib.mjs";
5	import { validateProviderPlan } from "./provider-plan.mjs";
6	
7	/** @typedef {{id: string, unitId: string, sourceDigest: string, start: number, end: number, replacement: string, actorId: string}} Edit */
8	/** @typedef {{editId: string, decision: "accept" | "retain", reasonCode: string, sourceDefect: string, invariantDelta: string}} VerificationDecision */
9	/** @typedef {{unitId: string, start: number, end: number, kind: "prose" | "fenced-code"}} SourceUnit */
10	
11	const DIGEST = /^[a-f0-9]{64}$/u;
12	const CODE = /^[A-Z][A-Z0-9_]*$/u;
13	const ISSUE_CODES = new Set(["AMBIGUOUS_RELATIONSHIP", "GRAMMATICAL_MISMATCH", "NOUN_STACKING", "REDUNDANCY", "TRANSLATIONESE", "UNNECESSARY_META_PROSE", "UNSUPPORTED_EMPHASIS", "USER_FACING_IMPLEMENTATION_JARGON"]);
14	const PROTECTED_KINDS = new Set(["fenced-code", "inline-code", "command", "markdown-target", "url", "email", "path", "quotation", "number-or-date", "user-defined", "glossary"]);
15	const GLOSSARY_STATUSES = new Set(["matched", "no-match", "unavailable", "limit-exceeded", "unsupported-normalization"]);
16	const GLOSSARY_POLICIES = new Set(["protect", "prefer", "allow", "avoid"]);
17	
18	/**
19	 * @param {unknown} value
20	 * @returns {{output: string, receipt: Record<string, unknown>}}
21	 */
22	export function finalizeRequest(value) {
23	  const request = requireObject(value, "request");
24	  if (request.schemaVersion !== SCHEMA_VERSION) throw new ContractError("REQUEST_SCHEMA_VERSION", "unsupported request schema version");
25	  if (request.mode !== "mcp" && request.mode !== "direct") throw new ContractError("MODE", "mode must be mcp or direct");
26	  const mode = request.mode;
27	  if (typeof request.source !== "string") throw new ContractError("SOURCE", "source must be a string");
28	  const source = request.source;
29	  const sourceDigest = sha256(source);
30	  const plan = validateProviderPlan(request.plan, { subagentsAvailable: request.subagentsAvailable === true });
31	  const actorIds = plan.actorIds;
32	  const manifest = requireObject(request.manifest, "manifest");
33	  const sourceUnitManifest = requireObject(request.sourceUnitManifest, "sourceUnitManifest");
34	  const selection = requireObject(request.selection, "selection");
35	  const editing = requireObject(request.editing, "editing");
36	  const verification = requireObject(request.verification, "verification");
37	  const warnings = new Set();
38	  let fallback = false;
39	
40	  if (!validProtectedManifest(manifest, source)) {
41	    warnings.add("SOURCE_MANIFEST_MISMATCH");
42	    fallback = true;
43	  }
44	
45	  const glossaryContext = validateGlossaryContext(mode, sourceDigest, request.glossaryMatchSet, manifest);
46	  for (const warning of glossaryContext.warnings) warnings.add(warning);
47	  if (!glossaryContext.valid) {
48	    warnings.add("GLOSSARY_MATCH_SET_INVALID");
49	    fallback = true;
50	  }
51	  const expectedGlossaryBinding = glossaryContext.binding;
52	  if (stableJson(selection.glossaryBinding) !== stableJson(expectedGlossaryBinding)
53	    || stableJson(editing.glossaryBinding) !== stableJson(expectedGlossaryBinding)
54	    || stableJson(verification.glossaryBinding) !== stableJson(expectedGlossaryBinding)) {
55	    warnings.add("GLOSSARY_BINDING_MISMATCH");
56	    fallback = true;
57	  }
58	
59	  /** @type {SourceUnit[]} */
60	  let units = [];
61	  if (!fallback) {
62	    const expectedUnits = createSourceUnitManifest(source, /** @type {any} */ (manifest));
63	    if (stableJson(sourceUnitManifest) !== stableJson(expectedUnits)) {
64	      warnings.add("SOURCE_UNIT_MANIFEST_MISMATCH");
65	      fallback = true;
66	    } else {
67	      units = /** @type {SourceUnit[]} */ (expectedUnits.units);
68	    }
69	  }
70	
71	  const unitById = new Map(units.map((unit) => [unit.unitId, unit]));
72	  const selectionByUnit = new Map();
73	  if (!validSelection(selection, sourceDigest, actorIds[0], unitById, source, expectedGlossaryBinding)) {
74	    warnings.add("SELECTION_CONTRACT_INVALID");
75	    fallback = true;
76	  } else {
77	    for (const decision of /** @type {any[]} */ (selection.decisions)) selectionByUnit.set(decision.unitId, decision);
78	    if (selection.status !== "ready") {
79	      warnings.add("SELECTION_NOT_READY");
80	      fallback = true;
81	    }
82	  }
83	
84	  const selectionDigest = sha256(stableJson(selection));
85	  /** @type {Edit[]} */
86	  const edits = [];
87	  if (!validEditingRoot(editing, sourceDigest, selectionDigest, actorIds[1], expectedGlossaryBinding)) {
88	    if (editing.selectionDigest === selectionDigest) warnings.add("EDIT_CONTRACT_INVALID");
89	    else warnings.add("SELECTION_DIGEST_MISMATCH");
90	    fallback = true;
91	  }
92	
93	  const rawEdits = Array.isArray(editing.edits) ? editing.edits : [];
94	  const editIds = new Set();
95	  for (const rawEdit of rawEdits) {
96	    if (!validEdit(rawEdit, source, sourceDigest, actorIds[1], editIds)) {
97	      warnings.add("EDIT_CONTRACT_INVALID");
98	      fallback = true;
99	      continue;
100	    }
101	    const edit = /** @type {Edit} */ (rawEdit);
102	    editIds.add(edit.id);
103	    edits.push(edit);
104	  }
105	  edits.sort((left, right) => left.start - right.start || left.end - right.end || left.id.localeCompare(right.id));
106	  for (let index = 1; index < edits.length; index += 1) {
107	    if (edits[index].start < edits[index - 1].end || (edits[index].start === edits[index - 1].start && edits[index].start === edits[index].end)) {
108	      warnings.add("EDIT_RANGES_OVERLAP");
109	      fallback = true;
110	    }
111	  }
112	
113	  if (!fallback && editing.candidateDigest !== sha256(applyEdits(source, edits))) {
114	    warnings.add("EDITING_DIGEST_MISMATCH");
115	    fallback = true;
116	  }
117	
118	  const editingDigest = sha256(stableJson(editing));
119	  if (!validVerificationRoot(verification, sourceDigest, editingDigest, actorIds[2], expectedGlossaryBinding)) {
120	    if (verification.editingDigest === editingDigest) warnings.add("VERIFICATION_CONTRACT_INVALID");
121	    else warnings.add("VERIFICATION_DIGEST_MISMATCH");
122	    fallback = true;
123	  }
124	  if (typeof request.rubricDigest !== "string" || !DIGEST.test(request.rubricDigest) || verification.rubricDigest !== request.rubricDigest) {
125	    warnings.add("VERIFICATION_RUBRIC_DIGEST_MISMATCH");
126	    fallback = true;
127	  }
128	  if (verification.globalDecision === "fallback") {
129	    warnings.add("VERIFIER_GLOBAL_FALLBACK");
130	    fallback = true;
131	  }
132	
133	  /** @type {Map<string, VerificationDecision>} */
134	  const decisionByEdit = new Map();
135	  const rawDecisions = Array.isArray(verification.decisions) ? verification.decisions : [];
136	  for (const rawDecision of rawDecisions) {
137	    if (!validVerificationDecision(rawDecision) || decisionByEdit.has(rawDecision.editId) || !editIds.has(rawDecision.editId)) {
138	      warnings.add("VERIFICATION_DECISION_INVALID");
139	      fallback = true;
140	      continue;
141	    }
142	    decisionByEdit.set(rawDecision.editId, /** @type {VerificationDecision} */ (rawDecision));
143	  }
144	
145	  const effectiveManifest = fallback
146	    ? manifest
147	    : addSelectionProtectedStrings(source, /** @type {any} */ (manifest), /** @type {any[]} */ (selection.decisions), unitById);
148	  const spans = Array.isArray(effectiveManifest.spans) ? effectiveManifest.spans : [];
149	  /** @type {Edit[]} */
150	  const accepted = [];
151	  /** @type {Edit[]} */
152	  const retained = [];
153	  for (const edit of edits) {
154	    const unit = unitById.get(edit.unitId);
155	    const selected = selectionByUnit.get(edit.unitId);
156	    if (!unit || !selected || selected.action !== "edit" || edit.start < unit.start || edit.end > unit.end || !selected.issueRanges.some((issue) => rangesOverlap(edit, issue))) {
157	      retained.push(edit);
158	      warnings.add("EDIT_OUT_OF_SCOPE_RETAINED");
159	      continue;
160	    }
161	    if (unit.kind === "fenced-code" || overlapsProtectedSpan(edit.start, edit.end, spans)) {
162	      retained.push(edit);
163	      warnings.add("PROTECTED_EDIT_RETAINED");
164	      continue;
165	    }
166	    if (!isMinimalEdit(source, edit)) {
167	      retained.push(edit);
168	      warnings.add("NON_MINIMAL_EDIT_RETAINED");
169	      continue;
170	    }
171	    const decision = decisionByEdit.get(edit.id);
172	    if (decision?.decision !== "accept") {
173	      retained.push(edit);
174	      if (!decision) warnings.add("VERIFICATION_DECISION_MISSING");
175	      continue;
176	    }
177	    accepted.push(edit);
178	  }
179	
180	  if (!fallback && accepted.length > 0 && !acceptedAssessmentIsSafe(verification.assessment)) {
181	    warnings.add("VERIFICATION_CONTRACT_INVALID");
182	    fallback = true;
183	  }
184	
185	  let output = source;
186	  if (!fallback) {
187	    output = applyEdits(source, accepted);
188	    const check = checkResult(source, output, effectiveManifest);
189	    if (check.decisions.protectedSpansPreserved !== true) {
190	      warnings.add("FINAL_PROTECTED_CHECK_FAILED");
191	      for (const warning of check.warnings) warnings.add(warning);
192	      fallback = true;
193	      output = source;
194	    }
195	  }
196	
197	  const applied = fallback ? [] : accepted;
198	  const allRetained = fallback ? edits : retained;
199	  if (fallback) warnings.add("GLOBAL_FALLBACK_APPLIED");
200	  const receipt = {
201	    schemaVersion: SCHEMA_VERSION,
202	    actorIds,
203	    digest: {
204	      source: sourceDigest,
205	      result: sha256(output),
206	      manifest: sha256(stableJson(effectiveManifest)),
207	    },
208	    length: { source: source.length, result: output.length },
209	    glossary: glossaryContext.summary,
210	    decisions: {
211	      mode,
212	      assurance: mode === "mcp" && !fallback ? "verified" : "unverified",
213	      status: fallback ? "fallback" : "finalized",
214	      appliedEditDigests: applied.map((edit) => sha256(edit.id)),
215	      retainedEditDigests: allRetained.map((edit) => sha256(edit.id)),
216	      fallback,
217	    },
218	    warnings: [...warnings].sort(),
219	  };
220	
221	  return { output, receipt };
222	}
223	
224	/** @param {{output: string, receipt: Record<string, unknown>}} result @param {"mcp" | "direct"} mode */
225	export function formatFinalizationResponse(result, mode) {
226	  if (mode === "mcp") return result.receipt;
227	  return { output: result.output, verificationStatus: "unverified", receipt: result.receipt };
228	}
229	
230	/** @param {"mcp" | "direct"} mode @param {string} sourceDigest @param {unknown} value @param {Record<string, unknown>} manifest */
231	function validateGlossaryContext(mode, sourceDigest, value, manifest) {
232	  const directBinding = { schemaVersion: SCHEMA_VERSION, mode: "none" };
233	  const directSummary = { mode: "none", status: "direct", id: null, version: null, contentDigest: null, matchSetDigest: null, matchCount: 0, warnings: [] };
234	  if (mode === "direct") return { valid: value === null, binding: directBinding, summary: directSummary, warnings: [] };
235	
236	  const invalidSummary = { mode: "mcp", status: "unavailable", id: null, version: null, contentDigest: null, matchSetDigest: null, matchCount: 0, warnings: [] };
237	  if (!value || typeof value !== "object" || Array.isArray(value)) return { valid: false, binding: mcpFailureBinding(sourceDigest), summary: invalidSummary, warnings: [] };
238	  const matchSet = /** @type {Record<string, unknown>} */ (value);
239	  if (!hasExactKeys(matchSet, ["schemaVersion", "status", "sourceDigest", "glossary", "matches", "matchSetDigest", "warnings"])
240	    || matchSet.schemaVersion !== SCHEMA_VERSION || matchSet.sourceDigest !== sourceDigest
241	    || typeof matchSet.status !== "string" || !GLOSSARY_STATUSES.has(matchSet.status)
242	    || !Array.isArray(matchSet.matches) || matchSet.matches.length > 256 || !Array.isArray(matchSet.warnings)) {
243	    return { valid: false, binding: mcpFailureBinding(sourceDigest), summary: invalidSummary, warnings: [] };
244	  }
245	  const status = /** @type {string} */ (matchSet.status);
246	  const warningSets = {
247	    matched: [],
248	    "no-match": [],
249	    unavailable: ["GLOSSARY_UNAVAILABLE"],
250	    "limit-exceeded": ["GLOSSARY_MATCH_LIMIT_EXCEEDED"],
251	    "unsupported-normalization": ["GLOSSARY_UNSUPPORTED_NORMALIZATION"],
252	  };
253	  const expectedWarnings = warningSets[status];
254	  if (stableJson(matchSet.warnings) !== stableJson(expectedWarnings)) return { valid: false, binding: mcpFailureBinding(sourceDigest), summary: invalidSummary, warnings: [] };
255	
256	  const available = status === "matched" || status === "no-match";
257	  const glossary = matchSet.glossary;
258	  const validGlossaryMetadata = glossary && typeof glossary === "object" && !Array.isArray(glossary)
259	    && hasExactKeys(glossary, ["id", "version", "contentDigest"])
260	    && glossary.id === "korean-prose-core" && glossary.version === "1.2.1"
261	    && typeof glossary.contentDigest === "string" && DIGEST.test(glossary.contentDigest);
262	  if (available) {
263	    if (!validGlossaryMetadata
264	      || typeof matchSet.matchSetDigest !== "string" || !DIGEST.test(matchSet.matchSetDigest)) {
265	      return { valid: false, binding: mcpFailureBinding(sourceDigest), summary: invalidSummary, warnings: [] };
266	    }
267	  } else if (matchSet.matchSetDigest !== null || (glossary !== null && (status !== "limit-exceeded" || !validGlossaryMetadata))) {
268	    return { valid: false, binding: mcpFailureBinding(sourceDigest), summary: invalidSummary, warnings: [] };
269	  }
270	
271	  const matches = /** @type {Record<string, unknown>[]} */ (matchSet.matches);
272	  if ((!available && matches.length !== 0) || (status === "matched" && matches.length === 0) || (status === "no-match" && matches.length !== 0)) {
273	    return { valid: false, binding: mcpFailureBinding(sourceDigest), summary: invalidSummary, warnings: [] };
274	  }
275	  for (const match of matches) {
276	    if (!match || typeof match !== "object" || Array.isArray(match)
277	      || !hasExactKeys(match, ["start", "end", "entryId", "policy", "canonicalForm", "priority"])
278	      || !Number.isInteger(match.start) || !Number.isInteger(match.end)
279	      || /** @type {number} */ (match.start) < 0 || /** @type {number} */ (match.end) <= /** @type {number} */ (match.start)
280	      || /** @type {number} */ (match.end) > /** @type {number} */ (manifest.sourceLength ?? 0)
281	      || typeof match.entryId !== "string" || !/^[a-z0-9][a-z0-9-]*$/u.test(match.entryId)
282	      || typeof match.policy !== "string" || !GLOSSARY_POLICIES.has(match.policy)
283	      || typeof match.canonicalForm !== "string" || match.canonicalForm.length === 0
284	      || !Number.isInteger(match.priority) || /** @type {number} */ (match.priority) < 0 || /** @type {number} */ (match.priority) > 1000) {
285	      return { valid: false, binding: mcpFailureBinding(sourceDigest), summary: invalidSummary, warnings: [] };
286	    }
287	  }
288	  if (available) {
289	    const digestInput = { schemaVersion: SCHEMA_VERSION, sourceDigest, glossary, matches };
290	    if (matchSet.matchSetDigest !== sha256(stableJson(digestInput))) return { valid: false, binding: mcpFailureBinding(sourceDigest), summary: invalidSummary, warnings: [] };
291	    const spans = Array.isArray(manifest.spans) ? manifest.spans : [];
292	    const protectMissing = matches.some((match) => match.policy === "protect" && !spans.some((span) => span.start <= match.start && span.end >= match.end));
293	    if (protectMissing) {
294	      const binding = bindingFromMatchSet(matchSet);
295	      return { valid: false, binding, summary: summaryFromBinding(binding), warnings: ["GLOSSARY_PROTECT_MISSING"] };
296	    }
297	  }
298	  const binding = bindingFromMatchSet(matchSet);
299	  return { valid: true, binding, summary: summaryFromBinding(binding), warnings: /** @type {string[]} */ (matchSet.warnings) };
300	}
301	
302	/** @param {string} sourceDigest */
303	function mcpFailureBinding(sourceDigest) {
304	  return { schemaVersion: SCHEMA_VERSION, mode: "mcp", status: "unavailable", sourceDigest, glossaryId: null, glossaryVersion: null, glossaryDigest: null, matchSetDigest: null, matchCount: 0, warnings: ["GLOSSARY_UNAVAILABLE"] };
305	}
306	
307	/** @param {Record<string, unknown>} matchSet */
308	function bindingFromMatchSet(matchSet) {
309	  const glossary = matchSet.glossary && typeof matchSet.glossary === "object" ? /** @type {Record<string, unknown>} */ (matchSet.glossary) : null;
310	  return {
311	    schemaVersion: SCHEMA_VERSION,
312	    mode: "mcp",
313	    status: matchSet.status,
314	    sourceDigest: matchSet.sourceDigest,
315	    glossaryId: glossary?.id ?? null,
316	    glossaryVersion: glossary?.version ?? null,
317	    glossaryDigest: glossary?.contentDigest ?? null,
318	    matchSetDigest: matchSet.matchSetDigest,
319	    matchCount: /** @type {unknown[]} */ (matchSet.matches).length,
320	    warnings: matchSet.warnings,
321	  };
322	}
323	
324	/** @param {Record<string, unknown>} binding */
325	function summaryFromBinding(binding) {
326	  return { mode: binding.mode, status: binding.status, id: binding.glossaryId, version: binding.glossaryVersion, contentDigest: binding.glossaryDigest, matchSetDigest: binding.matchSetDigest, matchCount: binding.matchCount, warnings: binding.warnings };
327	}
328	
329	/** @param {Record<string, unknown>} manifest @param {string} source */
330	function validProtectedManifest(manifest, source) {
331	  if (!hasExactKeys(manifest, ["schemaVersion", "sourceDigest", "sourceLength", "spans"]) || manifest.schemaVersion !== SCHEMA_VERSION || manifest.sourceDigest !== sha256(source) || manifest.sourceLength !== source.length || !Array.isArray(manifest.spans)) return false;
332	  const ids = new Set();
333	  let previousEnd = 0;
334	  for (const span of manifest.spans) {
335	    if (!span || typeof span !== "object" || Array.isArray(span) || !hasExactKeys(span, ["id", "kind", "start", "end", "text", "digest"])) return false;
336	    const item = /** @type {Record<string, unknown>} */ (span);
337	    if (typeof item.id !== "string" || !/^span-[0-9]{4}$/u.test(item.id) || ids.has(item.id) || typeof item.kind !== "string" || !PROTECTED_KINDS.has(item.kind) || !Number.isInteger(item.start) || !Number.isInteger(item.end)) return false;
338	    const start = /** @type {number} */ (item.start);
339	    const end = /** @type {number} */ (item.end);
340	    if (start < previousEnd || end <= start || end > source.length || typeof item.text !== "string" || item.text !== source.slice(start, end) || item.digest !== sha256(item.text)) return false;
341	    ids.add(item.id);
342	    previousEnd = end;
343	  }
344	  return true;
345	}
346	
347	/** @param {Record<string, unknown>} selection @param {string} sourceDigest @param {string} actorId @param {Map<string, SourceUnit>} unitById @param {string} source */
348	function validSelection(selection, sourceDigest, actorId, unitById, source, glossaryBinding) {
349	  if (!hasExactKeys(selection, ["schemaVersion", "actorId", "sourceDigest", "glossaryBinding", "status", "decisions"])) return false;
350	  if (selection.schemaVersion !== SCHEMA_VERSION || selection.actorId !== actorId || selection.sourceDigest !== sourceDigest || stableJson(selection.glossaryBinding) !== stableJson(glossaryBinding) || !["ready", "needs-input", "blocked"].includes(/** @type {string} */ (selection.status)) || !Array.isArray(selection.decisions)) return false;
351	  if (selection.decisions.length !== unitById.size) return false;
352	  const seen = new Set();
353	  for (const rawDecision of selection.decisions) {
354	    if (!rawDecision || typeof rawDecision !== "object" || Array.isArray(rawDecision) || !hasExactKeys(rawDecision, ["unitId", "action", "reasonCodes", "riskFlags", "additionalProtectedStrings", "issueRanges"])) return false;
355	    const decision = /** @type {Record<string, unknown>} */ (rawDecision);
356	    const unit = typeof decision.unitId === "string" ? unitById.get(decision.unitId) : undefined;
357	    if (!unit || seen.has(decision.unitId) || !["edit", "retain", "defer"].includes(/** @type {string} */ (decision.action))) return false;
358	    if (unit.kind === "fenced-code" && decision.action === "edit") return false;
359	    if (!validCodes(decision.reasonCodes) || !validCodes(decision.riskFlags) || !Array.isArray(decision.additionalProtectedStrings) || !Array.isArray(decision.issueRanges)) return false;
360	    const protectedStrings = decision.additionalProtectedStrings;
361	    if (new Set(protectedStrings).size !== protectedStrings.length || protectedStrings.some((item) => typeof item !== "string" || item.length === 0 || !source.slice(unit.start, unit.end).includes(item))) return false;
362	    if (decision.action === "edit") {
363	      if (decision.issueRanges.length === 0 || !validIssueRanges(decision.issueRanges, unit, source)) return false;
364	      const issueCodes = new Set(decision.issueRanges.map((issue) => issue.reasonCode));
365	      if (decision.reasonCodes.length !== issueCodes.size || decision.reasonCodes.some((code) => !issueCodes.has(code))) return false;
366	    } else if (decision.issueRanges.length !== 0) return false;
367	    seen.add(decision.unitId);
368	  }
369	  return true;
370	}
371	
372	/** @param {any[]} issues @param {SourceUnit} unit @param {string} source */
373	function validIssueRanges(issues, unit, source) {
374	  const seen = new Set();
375	  for (const issue of issues) {
376	    if (!issue || typeof issue !== "object" || Array.isArray(issue) || !hasExactKeys(issue, ["start", "end", "reasonCode"])) return false;
377	    if (!Number.isInteger(issue.start) || !Number.isInteger(issue.end) || issue.start < unit.start || issue.end > unit.end || issue.end <= issue.start) return false;
378	    if (!isUtf16Boundary(source, issue.start) || !isUtf16Boundary(source, issue.end) || !ISSUE_CODES.has(issue.reasonCode)) return false;
379	    const key = `${issue.start}:${issue.end}:${issue.reasonCode}`;
380	    if (seen.has(key)) return false;
381	    seen.add(key);
382	  }
383	  return true;
384	}
385	
386	/** @param {{start:number,end:number}} left @param {{start:number,end:number}} right */
387	function rangesOverlap(left, right) {
388	  if (left.start === left.end) return right.start < left.start && left.start < right.end;
389	  return left.start < right.end && right.start < left.end;
390	}
391	
392	/** @param {Record<string, unknown>} editing @param {string} sourceDigest @param {string} selectionDigest @param {string} actorId */
393	function validEditingRoot(editing, sourceDigest, selectionDigest, actorId, glossaryBinding) {
394	  return hasExactKeys(editing, ["schemaVersion", "actorId", "sourceDigest", "glossaryBinding", "selectionDigest", "edits", "candidateDigest"])
395	    && editing.schemaVersion === SCHEMA_VERSION
396	    && editing.actorId === actorId
397	    && editing.sourceDigest === sourceDigest
398	    && stableJson(editing.glossaryBinding) === stableJson(glossaryBinding)
399	    && editing.selectionDigest === selectionDigest
400	    && Array.isArray(editing.edits)
401	    && typeof editing.candidateDigest === "string"
402	    && DIGEST.test(editing.candidateDigest);
403	}
404	
405	/** @param {unknown} rawEdit @param {string} source @param {string} sourceDigest @param {string} actorId @param {Set<string>} ids */
406	function validEdit(rawEdit, source, sourceDigest, actorId, ids) {
407	  if (!rawEdit || typeof rawEdit !== "object" || Array.isArray(rawEdit) || !hasExactKeys(rawEdit, ["id", "unitId", "sourceDigest", "start", "end", "replacement", "actorId"])) return false;
408	  const edit = /** @type {Record<string, unknown>} */ (rawEdit);
409	  return typeof edit.id === "string" && edit.id.length > 0 && !ids.has(edit.id)
410	    && typeof edit.unitId === "string"
411	    && edit.sourceDigest === sourceDigest
412	    && Number.isInteger(edit.start) && Number.isInteger(edit.end)
413	    && /** @type {number} */ (edit.start) >= 0
414	    && /** @type {number} */ (edit.end) >= /** @type {number} */ (edit.start)
415	    && /** @type {number} */ (edit.end) <= source.length
416	    && isUtf16Boundary(source, /** @type {number} */ (edit.start))
417	    && isUtf16Boundary(source, /** @type {number} */ (edit.end))
418	    && typeof edit.replacement === "string"
419	    && edit.actorId === actorId;
420	}
421	
422	/** @param {string} source @param {number} index */
423	function isUtf16Boundary(source, index) {
424	  if (index <= 0 || index >= source.length) return true;
425	  const before = source.charCodeAt(index - 1);
426	  const after = source.charCodeAt(index);
427	  return !(before >= 0xD800 && before <= 0xDBFF && after >= 0xDC00 && after <= 0xDFFF);
428	}
429	
430	/** @param {Record<string, unknown>} verification @param {string} sourceDigest @param {string} editingDigest @param {string} actorId */
431	function validVerificationRoot(verification, sourceDigest, editingDigest, actorId, glossaryBinding) {
432	  if (!hasExactKeys(verification, ["schemaVersion", "actorId", "sourceDigest", "glossaryBinding", "editingDigest", "rubricDigest", "globalDecision", "decisions", "assessment"])) return false;
433	  if (verification.schemaVersion !== SCHEMA_VERSION || verification.actorId !== actorId || verification.sourceDigest !== sourceDigest || stableJson(verification.glossaryBinding) !== stableJson(glossaryBinding) || verification.editingDigest !== editingDigest || typeof verification.rubricDigest !== "string" || !DIGEST.test(verification.rubricDigest) || !["continue", "fallback"].includes(/** @type {string} */ (verification.globalDecision)) || !Array.isArray(verification.decisions)) return false;
434	  if (!verification.assessment || typeof verification.assessment !== "object" || Array.isArray(verification.assessment) || !hasExactKeys(verification.assessment, ["meaningPreservation", "majorMeaningChange", "registerCompliance", "protectedStrings", "terminologyJudgment", "pairPreference"])) return false;
435	  const assessment = /** @type {Record<string, unknown>} */ (verification.assessment);
436	  return ["pass", "fail", "uncertain"].includes(/** @type {string} */ (assessment.meaningPreservation))
437	    && typeof assessment.majorMeaningChange === "boolean"
438	    && ["pass", "fail", "uncertain"].includes(/** @type {string} */ (assessment.registerCompliance))
439	    && ["pass", "fail", "uncertain"].includes(/** @type {string} */ (assessment.protectedStrings))
440	    && ["pass", "fail", "uncertain", "not-applicable"].includes(/** @type {string} */ (assessment.terminologyJudgment))
441	    && ["candidate", "original", "tie", "neither"].includes(/** @type {string} */ (assessment.pairPreference));
442	}
443	
444	/** @param {any} decision */
445	function validVerificationDecision(decision) {
446	  return decision && typeof decision === "object" && !Array.isArray(decision)
447	    && hasExactKeys(decision, ["editId", "decision", "reasonCode", "sourceDefect", "invariantDelta"])
448	    && typeof decision.editId === "string" && decision.editId.length > 0
449	    && (decision.decision === "accept" || decision.decision === "retain")
450	    && typeof decision.reasonCode === "string" && CODE.test(decision.reasonCode)
451	    && ["GRAMMATICAL_MISMATCH", "NOUN_STACKING", "REDUNDANCY", "TRANSLATIONESE", "UNNECESSARY_META_PROSE", "UNSUPPORTED_EMPHASIS", "USER_FACING_IMPLEMENTATION_JARGON", "NONE"].includes(decision.sourceDefect)
452	    && ["NONE", "QUANTIFIER_SCOPE", "CONDITION_OR_TENSE", "MODALITY_OR_CERTAINTY", "ACTION_OR_AUTHORITY", "CLAIM_TYPE_OR_STRENGTH", "PREDICATE_ARGUMENT_STRUCTURE", "RHETORICAL_FUNCTION", "ACTOR_OR_TARGET", "TIME", "NEGATION", "CAUSAL_RELATION", "TERMINOLOGY", "UNCERTAIN"].includes(decision.invariantDelta)
453	    && (decision.decision !== "accept" || (decision.reasonCode === "MEANING_PRESERVED" && decision.sourceDefect !== "NONE" && decision.invariantDelta === "NONE"));
454	}
455	
456	/** @param {any} assessment */
457	function acceptedAssessmentIsSafe(assessment) {
458	  return assessment.meaningPreservation === "pass"
459	    && assessment.majorMeaningChange === false
460	    && assessment.registerCompliance === "pass"
461	    && assessment.protectedStrings === "pass"
462	    && (assessment.terminologyJudgment === "pass" || assessment.terminologyJudgment === "not-applicable")
463	    && assessment.pairPreference === "candidate";
464	}
465	
466	/** @param {string} source @param {Edit[]} edits */
467	function applyEdits(source, edits) {
468	  let output = source;
469	  for (const edit of [...edits].sort((left, right) => right.start - left.start || right.end - left.end)) {
470	    output = `${output.slice(0, edit.start)}${edit.replacement}${output.slice(edit.end)}`;
471	  }
472	  return output;
473	}
474	
475	/** @param {string} source @param {Edit} edit */
476	function isMinimalEdit(source, edit) {
477	  const original = source.slice(edit.start, edit.end);
478	  if (original === edit.replacement) return false;
479	  if (original.length === 0 || edit.replacement.length === 0) return true;
480	  const originalCodePoints = Array.from(original);
481	  const replacementCodePoints = Array.from(edit.replacement);
482	  return originalCodePoints[0] !== replacementCodePoints[0] && originalCodePoints.at(-1) !== replacementCodePoints.at(-1);
483	}
484	
485	/** @param {string} source @param {any} manifest @param {any[]} decisions @param {Map<string, SourceUnit>} unitById */
486	function addSelectionProtectedStrings(source, manifest, decisions, unitById) {
487	  const ranges = manifest.spans.map((span) => ({ start: span.start, end: span.end }));
488	  for (const decision of decisions) {
489	    const unit = unitById.get(decision.unitId);
490	    if (!unit) continue;
491	    for (const value of decision.additionalProtectedStrings) {
492	      for (let start = source.indexOf(value, unit.start); start !== -1 && start + value.length <= unit.end; start = source.indexOf(value, start + 1)) {
493	        ranges.push({ start, end: start + value.length });
494	      }
495	    }
496	  }
497	  ranges.sort((left, right) => left.start - right.start || left.end - right.end);
498	  const merged = [];
499	  for (const range of ranges) {
500	    const previous = merged.at(-1);
501	    if (previous && range.start < previous.end) previous.end = Math.max(previous.end, range.end);
502	    else merged.push({ ...range });
503	  }
504	  return {
505	    schemaVersion: SCHEMA_VERSION,
506	    sourceDigest: sha256(source),
507	    sourceLength: source.length,
508	    spans: merged.map((range, index) => {
509	      const text = source.slice(range.start, range.end);
510	      return { id: `span-${String(index + 1).padStart(4, "0")}`, kind: "user-defined", start: range.start, end: range.end, text, digest: sha256(text) };
511	    }),
512	  };
513	}
514	
515	/** @param {unknown} value */
516	function validCodes(value) {
517	  return Array.isArray(value) && new Set(value).size === value.length && value.every((item) => typeof item === "string" && CODE.test(item));
518	}
519	
520	/** @param {object} value @param {string[]} keys */
521	function hasExactKeys(value, keys) {
522	  const actual = Object.keys(value).sort();
523	  return actual.length === keys.length && actual.every((key, index) => key === [...keys].sort()[index]);
524	}
