28	/** @param {NodeJS.ReadableStream} [stream] */
29	export async function readJsonInput(stream = process.stdin) {
30	  let body = "";
31	  stream.setEncoding("utf8");
32	  for await (const chunk of stream) body += chunk;
33	  if (body.trim() === "") throw new ContractError("EMPTY_INPUT", "JSON input is required");
34	  return JSON.parse(body);
35	}
